    }
    const filters = new URLSearchParams({ filter: 'Completed', priorityFilter: 'High', dueFrom: '2024-02-28', dueThrough: '2024-03-01' });
    location = '/projects/1?' + filters;
    html = await get(location);
    assert.deepEqual(titles(html), ['Middle']);
